#!/usr/bin/env python3
"""runs/status_speedfix.md: the two speed fixes (horizon sanity rule, near-band preference, both) on top of w32mean
and w32mean_vwwide (speedfix_flow.sh, speedfix_eval.sh). Reads only run outputs."""
import hashlib
import json
from pathlib import Path

R = Path('runs')
O = R / 'speedfix'


def read(p, missing='(not available)'):
    p = Path(p)
    return p.read_text().strip() if p.is_file() else missing


def main():
    L = ['# Status: speed fixes on top of w32mean / w32mean_vwwide', '',
         'Generated by `fermarble/jobs/status_speedfix.py`. Nothing was uploaded. All parameters fitted on train '
         '(`oracle.py --speedfix-tune`), reported on val with the official evaluator.', '']
    for b in ('w32mean', 'vwwide'):
        best = json.loads((O / f'tune-{b}/speedfix_best.json').read_text()) if (O / f'tune-{b}/speedfix_best.json').is_file() else {}
        L += [f'## Base {b}', '', 'Fitted on train (oracle; means over all dev clips):', '',
              '| family | chosen | train (base) | val (base) | train better/worse | val better/worse |', '|---|---|---|---|---|---|']
        for fam, r in best.items():
            L.append(f"| {fam} | {r['label']} | {r['train']:.3f} ({r['train_base']:.3f}) | {r['val']:.3f} ({r['val_base']:.3f}) | "
                     f"{r['train_better']}/{r['train_worse']} | {r['val_better']}/{r['val_worse']} |")
        L += ['', read(O / f'compare-{b}.md'), '']
        for fam in ('hs', 'near', 'hs+near'):
            n = fam.replace('+', '')
            fires = json.loads(read(O / f'speed-{b}-{n}.fires.json', '{}'))
            if fires:
                on = {s: [f"{k[5:]} ({v['replaced']:.0%})" for k, v in sorted(fires.items()) if v['split'] == s and v['replaced'] > 0]
                      for s in ('dev', 'test')}
                L.append(f"- {fam}: the horizon rule fires on dev {', '.join(on['dev']) or 'none'}; test {', '.join(on['test']) or 'none'} "
                         '(share of flow pairs replaced)')
            L += [f"- {fam}: test clips whose speed changes: {read(O / f'diag-{b}-{n}.changed', '') or 'none'}", '',
                  read(O / f'diag-{b}-{n}.md'), '']
    L += ['## Bundles (validated, not uploaded)', '']
    bs = sorted(R.glob('submission_test_pi3x_ir_kwide_crop_ens_w32mean*_sf-*.json'))
    L += [f'- `{p}` (sha256 {hashlib.sha256(p.read_bytes()).hexdigest()})' for p in bs] or \
         ['- none (no variant beats its base on train and val and passes the diagnostics)']
    (R / 'status_speedfix.md').write_text('\n'.join(L) + '\n')
    print('written', R / 'status_speedfix.md')


if __name__ == '__main__':
    main()
